#!/usr/bin/env python3
"""Pinned transition workload DWARF profile; requires explicit --run-perf."""
import argparse,hashlib,json,os,pathlib,platform,re,subprocess,time
ROOT=pathlib.Path('/tmp/medaka-headroom-run-85c364304')
OUT=pathlib.Path('/tmp/medaka-transition-profile-85c364304')
ARMS={'baseline_AS':ROOT/'baseline_AS/workload','boehm_inline':ROOT/'boehm_inline/workload','boehm_caller_inline':ROOT/'boehm_caller_inline/workload'}
SOURCES={'baseline_gc':ROOT/'baseline_AS/gc.c','gc_header':ROOT/'baseline_AS/gc.h','harness':ROOT/'baseline_AS/harness.c','transition_harness':ROOT/'baseline_AS/transition.c.inc','workload':ROOT/'baseline_AS/workload.c','policy_reset':ROOT/'baseline_AS/policy_reset.c.inc','boehm_gc':ROOT/'boehm_caller_inline/gc.c','boehm_adapter':ROOT/'boehm_caller_inline/boehm_adapter.c','boehm_header':ROOT/'boehm_caller_inline/boehm_caller.h','boehm_inline_adapter':ROOT/'boehm_inline/boehm_adapter.c'}
BIN_EXPECTED={'baseline_AS':'001f72cf307cac83d8689012b9dc1baca78e37c4afd273925909f0c11599ab5b','boehm_caller_inline':'98f1fc7e13d38e446eb282da1740735d462dabf074f29ea3b6861f6246143691','boehm_inline':'7c6d08e7fafb360c667b7957801f4befe0ed82a9708d6bb58e763b90cce8985a'}
SOURCE_EXPECTED={'baseline_gc':'8b3d4bf65beccb9a019d2330f8266fc5261120140d94b611981add3b720876b4','gc_header':'c70257e8bb754ac649db073f7aad9960a6a734273b77bc213de14fc45d94cff0','transition_harness':'e056f3bc8ced6061e908e6990156a42cf2144dd03e1ce4e94b69941e57120f53','boehm_gc':'8b3d4bf65beccb9a019d2330f8266fc5261120140d94b611981add3b720876b4'}
REPEATS=50; ARGS=('transition','1000000','8000000','65536','262136')
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def main():
 ap=argparse.ArgumentParser(); ap.add_argument('--run-perf',action='store_true',help='record the frozen 50x2 sequential DWARF matrix; do not use before parent releases CPU slot'); args=ap.parse_args()
 bins={n:{'path':str(p),'sha256':sha(p)} for n,p in ARMS.items()}
 assert {n:v['sha256'] for n,v in bins.items()}==BIN_EXPECTED
 src={n:{'path':str(p),'sha256':sha(p)} for n,p in SOURCES.items()}
 for n,d in SOURCE_EXPECTED.items():assert src[n]['sha256']==d,(n,src[n]['sha256'],d)
 commands={n:['perf','record','--call-graph','dwarf,16384','-F','199','-o','<data>','--',str(ARMS[n]),*ARGS] for n in ARMS}
 meta={'schema':'medaka.transition-reuse-dwarf-profile-prep.v1','source_commit':'85c364304684c44c544957c8ba2b180d15d736c5','binaries':bins,'sources':src,'commands':commands,'repeats_per_arm':REPEATS,'profile_arguments':ARGS,'perf':'perf version 6.12.95','sample_config':'cycles:P at 199Hz, DWARF callchain 16384 bytes, one fresh process per data file','environment_policy':'all GC_* unset; match the transition harness runs; Boehm heap_init sets free space divisor 1 internally','focus':'phase samples in transition_build under transition_workload (anchor build contributes about 0.2% of allocation count); separate retained construction via transition_retain_then_drop; attribute custom new_pool/calloc/new_old versus promote/scan_promote/major_collect mark/sweep and Boehm allocation/full-collection paths. Include historical boehm_inline and stronger boehm_caller_inline. Inclusive groups overlap.','timing_claims':'CPU profile only; do not use perf-instrumented elapsed seconds as ordinary timing evidence','harness_cli':'transition RETAIN CHURN WINDOW NURSERY; baseline validation checksum expected 40640742562500; source transition oracle bounds every chain and exact-checks sentinels/ordinals'}
 meta['profile_driver']=str(pathlib.Path(__file__));meta['profile_driver_sha256']=sha(pathlib.Path(__file__))
 (OUT/'profile-prep.json').write_text(json.dumps(meta,indent=2)+'\n')
 print(json.dumps({'prepared':True,'profile_driver_sha256':meta['profile_driver_sha256'],'binary_sha256':{k:v['sha256'] for k,v in bins.items()},'output':str(OUT/'profile-prep.json')}))
 if not args.run_perf:return
 version=subprocess.run(['perf','--version'],capture_output=True,text=True,check=True).stdout.strip()
 assert version=='perf version 6.12.95',version
 env={k:v for k,v in os.environ.items() if not k.startswith('GC_')}
 data_dir=OUT/'raw';data_dir.mkdir(exist_ok=True)
 records=[];start=time.monotonic()
 for arm,binary in ARMS.items():
  for rep in range(REPEATS):
   prefix=f'{arm}-{rep:02d}';data=data_dir/(prefix+'.data')
   cmd=['perf','record','--call-graph','dwarf,16384','-F','199','-o',str(data),'--',str(binary),*ARGS]
   t=time.monotonic();p=subprocess.run(cmd,env=env,text=True,capture_output=True,timeout=120);elapsed=time.monotonic()-t
   out=(data_dir/(prefix+'.stdout'));err=(data_dir/(prefix+'.stderr'));out.write_text(p.stdout);err.write_text(p.stderr)
   row=None
   for line in p.stdout.splitlines():
    if line.startswith('{'):
     try: row=json.loads(line)
     except json.JSONDecodeError: pass
   assert p.returncode==0,(arm,rep,p.returncode,p.stderr[-2000:])
   assert row and row['profile']=='transition' and row['retain_count']==1000000 and row['churn_count']==8000000 and row['window_count']==65536 and row['checksum']==40640742562500,(arm,rep,row)
   m=re.search(r'\((\d+) samples\)',p.stderr)
   rec={'arm':arm,'repeat':rep,'command':cmd,'returncode':p.returncode,'runner_wall_seconds':elapsed,'data_path':str(data),'data_sha256':sha(data),'data_bytes':data.stat().st_size,'perf_sample_count':int(m.group(1)) if m else None,'stdout_path':str(out),'stdout_sha256':sha(out),'stderr_path':str(err),'stderr_sha256':sha(err),'workload':row}
   records.append(rec)
   with (OUT/'profile-recording.jsonl').open('a') as f:f.write(json.dumps(rec,separators=(',',':'))+'\n')
   print(json.dumps({'done':len(records),'total':2*REPEATS,'arm':arm,'repeat':rep,'samples':rec['perf_sample_count'],'elapsed_total':time.monotonic()-start}),flush=True)
 assert {n:sha(p) for n,p in ARMS.items()}==BIN_EXPECTED,'binary drift'
 meta.update({'perf':version,'profile_runs':records,'row_count':len(records),'total_runner_wall_seconds':time.monotonic()-start,'results_sha256':sha(OUT/'profile-recording.jsonl')})
 (OUT/'profile-prep.json').write_text(json.dumps(meta,indent=2)+'\n')
 print(json.dumps({'complete':True,'rows':len(records),'results_sha256':meta['results_sha256']}))
if __name__=='__main__': main()

