#define main prototype_original_main
#include "workload.c"
#undef main
#include "transition.c.inc"
#include "policy_reset.c.inc"
#include <errno.h>
#ifndef USE_BOEHM
static size_t threshold_probe(size_t before_sweep_bytes,size_t live,size_t nursery) {
  (void)before_sweep_bytes;
  size_t result = live > (SIZE_MAX - nursery * 4) / 2
      ? SIZE_MAX : live * 2 + nursery * 4;
  return result;
}
#endif

static size_t number(const char *s, int positive) {
  char *end; errno = 0;
  if (!s[0] || s[0] < '0' || s[0] > '9') { fputs("invalid positive integer\n", stderr); exit(2); }
  unsigned long long v = strtoull(s, &end, 10);
  if (errno || *end || (positive && !v) || v > SIZE_MAX) { fputs("invalid integer\n", stderr); exit(2); }
  return (size_t)v;
}
static void point(const TransitionPoint *p) {
  printf("{\"process_peak_rss_bytes\":%zu", p->process_peak_rss_bytes);
#ifndef USE_BOEHM
  printf(",\"major_count\":%" PRIu64 ",\"minor_count\":%" PRIu64
      ",\"copied_bytes\":%" PRIu64 ",\"reclaimed_bytes\":%" PRIu64
      ",\"old_live_bytes\":%zu,\"peak_old_bytes\":%zu,\"peak_accounted_bytes\":%zu"
      ",\"pool_reserved_bytes\":%zu,\"large_reserved_bytes\":%zu",
      p->major_count,p->minor_count,p->copied_bytes,p->reclaimed_bytes,
      p->old_live_bytes,p->peak_old_bytes,p->peak_accounted_bytes,
      p->pool_reserved_bytes,p->large_reserved_bytes);
#else
  printf(",\"custom_memory\":null");
#endif
  putchar('}');
}
int main(int argc, char **argv) {
#ifndef USE_BOEHM
  if (argc == 5 && !strcmp(argv[1], "--policy-math")) {
    size_t before=number(argv[2],0),live=number(argv[3],0),nursery=number(argv[4],1);
    if (live>before || nursery>SIZE_MAX/4 || nursery<32) return 2;
    printf("%zu\n",threshold_probe(before,live,nursery)); return 0;
  }
#endif
  if (argc == 2 && !strcmp(argv[1], "--reset")) {
#ifndef USE_BOEHM
    policy_reset_selftest(POLICY_ADAPTIVE); puts("policy reset passed"); return 0;
#else
    fputs("reset is custom-only\n", stderr); return 2;
#endif
  }
  if (argc != 6 || strcmp(argv[1], "transition")) {
    fputs("usage: --reset | transition RETAIN CHURN WINDOW NURSERY\n", stderr); return 2;
  }
  size_t retain=number(argv[2],1),churn=number(argv[3],1),window=number(argv[4],1),nursery=number(argv[5],1);
  if (retain >= 1000000000 || churn >= 1000000000 || nursery < 32 || nursery > SIZE_MAX/4
      || (uint64_t)retain + churn + (retain+63)/64 >= 1000000000) {
    fputs("transition input outside bounds\n",stderr); return 2;
  }
  heap_init(nursery); prepare_workload();
  TransitionReport report;
  double started=now(); uint64_t checksum=transition_workload(retain,churn,window,&report);
  double elapsed=now()-started;
  printf("{\"profile\":\"transition\",\"retain_count\":%zu,\"churn_count\":%zu,"
      "\"window_count\":%zu,\"anchor_count\":%zu,\"checksum\":%" PRIu64
      ",\"elapsed_seconds\":%.9f,\"construction_seconds\":%.9f,\"drop_churn_seconds\":%.9f,"
      "\"final_collect_seconds\":%.9f,\"harness_fixed_bytes\":%zu,",
      retain,churn,window,report.anchor_count,checksum,elapsed,report.construction_seconds,
      report.drop_churn_seconds,report.final_collect_seconds,sizeof report+sizeof layouts);
  print_stats(); printf(",\"before_drop\":"); point(&report.before_drop);
  printf(",\"after_churn\":"); point(&report.after_churn);
  printf(",\"after_final\":"); point(&report.after_final); puts("}");
  heap_destroy(); return 0;
}

policy_reset.text:
/* Custom-only correctness fixture, not part of timing. adaptive=0 checks the committed
   policy, adaptive=1 checks factor4.patch. Start with no initialized heap. */
#ifndef USE_BOEHM
static void policy_reset_selftest(int adaptive) {
  const size_t nursery = 4096, cell_bytes = sizeof(Word) * 4;
  Word values[8] = {0}; Root roots[8];
  heap_init(nursery);
  for (size_t i = 0; i < 8; ++i) {
    root_push(&roots[i], &values[i]);
    values[i] = allocate(3, 0); store(values[i], 0, integer(i + 1));
  }
  /* B=8 cells after minor promotion, L=8, R=0. */
  major_collect();
  assert(stats.old_object_count == 8 && stats.old_live_bytes == 8 * cell_bytes);
  assert(gc_fast.old_limit == (adaptive ? 4 : 2) * 8 * cell_bytes + 4 * nursery);
  /* B=8, L=7, R=1: exactly the one-eighth low-reclamation boundary. */
  values[7] = 0; major_collect();
  assert(stats.old_object_count == 7 && stats.old_live_bytes == 7 * cell_bytes);
  assert(gc_fast.old_limit == (adaptive ? 4 : 2) * 7 * cell_bytes + 4 * nursery);
  /* B=7, L=5, R=2: a formerly low-reclamation heap must reset immediately. */
  values[6] = values[5] = 0; major_collect();
  assert(stats.old_object_count == 5 && stats.old_live_bytes == 5 * cell_bytes);
  assert(gc_fast.old_limit == 2 * 5 * cell_bytes + 4 * nursery);
  /* B before minor is only5 cells, after minor is8; all8 remain live. */
  for (size_t i = 5; i < 8; ++i) {
    values[i] = allocate(3, 0); store(values[i], 0, integer(i + 1));
  }
  major_collect();
  assert(stats.old_object_count == 8 && stats.old_live_bytes == 8 * cell_bytes);
  assert(gc_fast.old_limit == (adaptive ? 4 : 2) * 8 * cell_bytes + 4 * nursery);
  for (size_t i = 0; i < 8; ++i) assert(load(values[i], 0) == integer(i + 1));
  for (size_t i = 0; i < 8; ++i) values[i] = 0;
  major_collect();
  assert(stats.old_live_bytes == 0 && stats.old_object_count == 0);
  assert(stats.pool_reserved_bytes == 0 && gc_fast.old_limit == 4 * nursery);
  assert(stats.copied_bytes == 11 * cell_bytes);
  assert(stats.reclaimed_bytes == 11 * cell_bytes);
  for (size_t i = 8; i-- > 0;) root_pop(&roots[i]);
  heap_destroy();
}
#endif

transition_harness.text:
/* Include after workload.c's work_allocate/work_store, sum_list and now helpers.
   Both custom and Boehm arms compile the same mutator. The caller prepares
   layouts and initializes the heap before calling this workload. */
typedef struct TransitionPoint {
  uint64_t major_count, minor_count, copied_bytes, reclaimed_bytes;
  size_t old_live_bytes, peak_old_bytes, peak_accounted_bytes;
  size_t pool_reserved_bytes, large_reserved_bytes;
  size_t process_peak_rss_bytes;
} TransitionPoint;
typedef struct TransitionReport {
  size_t retain_count, anchor_count, churn_count, window_count;
  double construction_seconds, drop_churn_seconds, final_collect_seconds;
  TransitionPoint before_drop, after_churn, after_final;
} TransitionReport;

static TransitionPoint transition_point(void) {
  struct rusage usage;
  int status = getrusage(RUSAGE_SELF, &usage); assert(status == 0);
#ifdef __APPLE__
  size_t rss_bytes = (size_t)usage.ru_maxrss;
#else
  size_t rss_bytes = (size_t)usage.ru_maxrss * 1024;
#endif
  return (TransitionPoint){stats.major_count, stats.minor_count,
      stats.copied_bytes, stats.reclaimed_bytes, stats.old_live_bytes,
      stats.peak_old_bytes, stats.peak_accounted_bytes,
      stats.pool_reserved_bytes, stats.large_reserved_bytes, rss_bytes};
}

/* The independent oracle knows every node's ordinal, sentinel and successor.
   Traversal is bounded even if a faulty collector introduces a cycle. */
static __attribute__((noinline)) uint64_t
transition_sum_exact(Word node, uint64_t base, size_t count) {
  uint64_t total = 0;
  for (size_t remaining = count; remaining; --remaining) {
    uint64_t expected = base + remaining - 1;
    assert(node);
    assert(load(node, 0) == integer(expected));
    assert(load(node, 2) == integer(expected ^ UINT64_C(0x5a5a)));
    total += unbox(load(node, 0));
    node = load(node, 1);
  }
  assert(node == 0);
  return total;
}

/* slot is already registered by the caller; reload it after every allocation. */
static __attribute__((noinline)) void
transition_build(Word *slot, size_t count, uint64_t base) {
  assert(*slot == 0);
  for (size_t i = 0; i < count; ++i) {
    Word node = work_allocate(list_layout());
    work_store(list_layout(), node, 0, integer(base + i));
    work_store(list_layout(), node, 1, *slot);
    work_store(list_layout(), node, 2, integer((base + i) ^ UINT64_C(0x5a5a)));
    *slot = node;
  }
}

/* Return only the numeric checksum; the caller never receives a pointer to
   this graph. Its physical root frame ends before continued churn begins. */
static __attribute__((noinline)) uint64_t
transition_retain_then_drop(size_t count, uint64_t base, double started,
    TransitionReport *report) {
  Word retained = 0; Root r;
  root_push(&r, &retained);
  transition_build(&retained, count, base);
  report->construction_seconds = now() - started;
  uint64_t checksum = transition_sum_exact(retained, base, count);
  report->before_drop = transition_point();
  retained = 0; root_pop(&r);
  return checksum;
}

static uint64_t transition_workload(size_t retain_count, size_t churn_count,
    size_t window_count, TransitionReport *report) {
  assert(retain_count > 0 && churn_count > 0 && window_count > 0);
  /* These bounds make tagged ordinals and the closed-form checksum safe. */
  assert(retain_count < UINT64_C(1000000000));
  assert(churn_count < UINT64_C(1000000000));
  size_t anchor_count = (retain_count + 63) / 64;
  uint64_t total_count = (uint64_t)anchor_count + retain_count + churn_count;
  assert(total_count < UINT64_C(1000000000));
  *report = (TransitionReport){.retain_count = retain_count,
      .anchor_count = anchor_count, .churn_count = churn_count,
      .window_count = window_count};
  Word anchor = 0, head = 0;
  Root a, h;
  double started = now();
  root_push(&a, &anchor);
  transition_build(&anchor, anchor_count, 0);
  uint64_t total = transition_retain_then_drop(retain_count, anchor_count,
      started, report);
  total += transition_sum_exact(anchor, 0, anchor_count);

  /* Deliberately no collection at this phase boundary: otherwise a forced
     reclaim would hide the automatic headroom policy's retention tradeoff. */
  started = now(); root_push(&h, &head);
  for (size_t completed = 0; completed < churn_count;) {
    size_t chunk = churn_count - completed;
    if (chunk > window_count) chunk = window_count;
    uint64_t base = (uint64_t)anchor_count + retain_count + completed;
    transition_build(&head, chunk, base);
    total += transition_sum_exact(head, base, chunk);
    head = 0;
    completed += chunk;
  }
  report->drop_churn_seconds = now() - started;
  report->after_churn = transition_point();
  assert(total == total_count * (total_count - 1) / 2);
  observed = total;

  started = now(); major_collect();
  report->final_collect_seconds = now() - started;
  report->after_final = transition_point();
  assert(transition_sum_exact(anchor, 0, anchor_count)
      == (uint64_t)anchor_count * (anchor_count - 1) / 2);
#ifndef USE_BOEHM
  /* Only after a collection is this an exact live-size assertion. */
  assert(stats.old_object_count == anchor_count);
  assert(stats.old_live_bytes == anchor_count * (old_header_size() + 3 * sizeof(Word)));
#endif
  anchor = head = 0; root_pop(&h); root_pop(&a);
  return total;
}

workload.text:
#define _POSIX_C_SOURCE 200809L
#include "gc.h"
#include <assert.h>
#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/resource.h>
#ifdef USE_BOEHM
#include <gc/gc.h>
#endif

static volatile uint64_t observed;
static GcLayout layouts[11];
static const size_t sized_words[] = {2, 3, 7, 16, 63, 64, 65, 127};
static const uint64_t sized_masks[] = {2, 2, 2, 0, 2, UINT64_C(1) << 63,
                                      2 | (UINT64_C(1) << 63), 0};
static void prepare_workload(void) {
  layouts[0] = prepare_layout(3, 2);
  layouts[1] = prepare_layout(3, 6);
  layouts[2] = prepare_layout(3, 0);
  for (size_t i = 0; i < 8; ++i) layouts[i + 3] = prepare_layout(sized_words[i], sized_masks[i]);
}
static inline GcLayout list_layout(void) { return (GcLayout){3, 2, layouts[0].info, layouts[0].epoch}; }
static inline GcLayout tree_layout(void) { return (GcLayout){3, 6, layouts[1].info, layouts[1].epoch}; }
static inline GcLayout atomic_layout(void) { return (GcLayout){3, 0, layouts[2].info, layouts[2].epoch}; }
static inline __attribute__((always_inline)) Word work_allocate(GcLayout layout) {
#if defined(INLINE_ALLOC)
  return allocate_prepared(layout);
#elif defined(USE_PREPARED) || defined(USE_PREPARED_ALLOC)
  return allocate_prepared_out_of_line(layout);
#else
  return allocate(layout.words, layout.mask);
#endif
}
static inline __attribute__((always_inline)) void work_store(GcLayout layout, Word object, size_t index, Word value) {
#if defined(INLINE_STORE)
  store_prepared(layout, object, index, value);
#elif defined(USE_PREPARED)
  store_prepared_out_of_line(layout, object, index, value);
#else
  (void)layout; store(object, index, value);
#endif
}
static uint64_t sum_sized(Word node) {
  uint64_t total = 0;
  while (node) {
    uint64_t encoded = unbox(load(node, 0)); size_t shape = encoded & 7;
    total += encoded >> 3; node = load(node, shape == 5 ? 63 : 1);
  }
  return total;
}
static uint64_t sum_list(Word node) {
  uint64_t total = 0;
  while (node) { total += unbox(load(node, 0)); node = load(node, 1); }
  return total;
}
static Word tree(size_t count, uint64_t *id) {
  if (!count) return 0;
  Word left = 0, right = 0;
  Root l, r; root_push(&l, &left); root_push(&r, &right);
  left = tree(count / 2, id);
  right = tree(count - count / 2 - 1, id);
  Word result = work_allocate(tree_layout());
  work_store(tree_layout(), result, 0, integer((*id)++));
  work_store(tree_layout(), result, 1, left); work_store(tree_layout(), result, 2, right);
  root_pop(&r); root_pop(&l); return result;
}
static uint64_t sum_tree(Word node) {
  return node ? unbox(load(node, 0)) + sum_tree(load(node, 1)) + sum_tree(load(node, 2)) : 0;
}
static void selftest(const char *only) {
  Word a = 0, b = 0; Root ra, rb;
  root_push(&ra, &a); root_push(&rb, &b);
  if (!only || strcmp(only, "root") == 0) {
    a = allocate(3, 2); store(a, 0, integer(17));
#ifndef USE_BOEHM
    Word before = a;
#endif
    minor_collect();
#ifndef USE_BOEHM
    assert(a != before);
#endif
    assert(load(a, 0) == integer(17));
  }
  if (!only || strcmp(only, "barrier") == 0) {
    a = allocate(3, 2); minor_collect();
    Word child = allocate(3, 2); store(child, 0, integer(29));
    store(a, 1, child); minor_collect();
#ifndef USE_BOEHM
    assert(load(a, 1) != child);
#endif
    assert(load(load(a, 1), 0) == integer(29));
  }
  if (!only) {
    a = allocate(3, 6); b = allocate(3, 6);
    store(a, 0, integer(11)); store(b, 0, integer(23));
    store(a, 1, b); store(a, 2, b); store(b, 1, a);
    minor_collect(); major_collect();
    assert(load(a, 1) == b && load(a, 2) == b && load(b, 1) == a);
    assert(load(b, 0) == integer(23));
    b = a; minor_collect(); assert(a == b);
    a = b = 0; major_collect();
#ifndef USE_BOEHM
    assert(stats.old_live_bytes == 0);
#endif
    for (size_t i = 0; i < 200; ++i) {
      b = allocate(3, 2); store(b, 0, integer(i)); store(b, 1, a); a = b; b = 0;
    }
    major_collect(); assert(sum_list(a) == 19900);
    a = 0; major_collect();
#ifndef USE_BOEHM
    assert(stats.old_live_bytes == 0 && stats.minor_count > 3);
#endif
    a = allocate(4096, 0); store(a, 4095, integer(91));
    major_collect(); assert(load(a, 4095) == integer(91));
    a = 0; major_collect();
#ifndef USE_BOEHM
    assert(stats.old_live_bytes == 0);
#endif
    for (size_t i = 0; i < 100; ++i) {
      a = allocate(4096, 0); store(a, 4095, integer(i));
    }
    major_collect(); assert(load(a, 4095) == integer(99));
    a = 0; major_collect();
#ifndef USE_BOEHM
    assert(stats.old_live_bytes == 0);
    a = allocate(3, 0); b = allocate(3, 2);
    /* A pointer-looking payload must not be visited under the atomic descriptor. */
    ((Word *)a)[0] = b; b = 0; major_collect();
    assert(stats.old_live_bytes == old_header_size() + 3 * sizeof(Word));
    a = 0; major_collect(); assert(stats.old_live_bytes == 0);
#endif
  }
  a = b = 0; root_pop(&rb); root_pop(&ra); major_collect();
  puts("selftest passed");
}
static uint64_t workload(const char *profile, size_t count) {
  Word head = 0, anchor = 0; Root h, a;
  root_push(&h, &head); root_push(&a, &anchor);
  uint64_t total = 0;
  if (strcmp(profile, "tree") == 0) {
    uint64_t id = 0; head = tree(count, &id); total = sum_tree(head);
  } else if (strcmp(profile, "atomic") == 0) {
    for (size_t i = 0; i < count; ++i) {
      head = work_allocate(atomic_layout()); work_store(atomic_layout(), head, 0, integer(i));
      work_store(atomic_layout(), head, 1, integer(i ^ 123)); work_store(atomic_layout(), head, 2, integer(0));
      total += unbox(load(head, 0));
    }
  } else if (strcmp(profile, "mixed") == 0) {
    for (size_t i = 0; i < count; ++i) {
      Word node = work_allocate(list_layout()); work_store(list_layout(), node, 0, integer(i));
      if (i % 64 == 0) { work_store(list_layout(), node, 1, anchor); anchor = node; }
      else { work_store(list_layout(), node, 1, head); head = node; }
      total += unbox(load(node, 0));
      if ((i + 1) % 64 == 0) head = 0;
    }
    head = 0;
    uint64_t retained = (count + 63) / 64;
    assert(sum_list(anchor) == 64 * retained * (retained - 1) / 2);
  } else if (strcmp(profile, "sizes") == 0) {
    Word atomic_roots[2] = {0, 0}; Root r0, r1;
    root_push(&r0, &atomic_roots[0]); root_push(&r1, &atomic_roots[1]);
    uint64_t retained_sum = 0, atomic_ids[2] = {0, 0};
    size_t retained_bytes = 0;
    for (size_t i = 0; i < count; ++i) {
      size_t shape = i & 7; GcLayout layout = layouts[shape + 3];
      Word node = work_allocate(layout);
      work_store(layout, node, 0, integer(((uint64_t)i << 3) | shape));
      /* The 61-step retention schedule visits every shape in the eight-step cycle. */
      int retained = (i + 1) % 61 == 0;
      if (layout.mask) {
        Word next = retained ? anchor : head;
        if (layout.mask & 2) work_store(layout, node, 1, next);
        if (layout.mask & (UINT64_C(1) << 63)) work_store(layout, node, 63, next);
        if (retained) {
          anchor = node; retained_sum += i;
          retained_bytes += old_header_size() + layout.words * sizeof(Word);
        } else head = node;
      } else {
        work_store(layout, node, layout.words - 1, integer(i ^ 123));
        if (retained) { size_t slot = shape == 3 ? 0 : 1; atomic_roots[slot] = node; atomic_ids[slot] = i; }
      }
      total += unbox(load(node, 0)) >> 3;
      if ((i + 1) % 64 == 0) head = 0;
    }
    head = 0; assert(sum_sized(anchor) == retained_sum);
    for (size_t slot = 0; slot < 2; ++slot) {
      if (atomic_roots[slot]) {
        assert((unbox(load(atomic_roots[slot], 0)) >> 3) == atomic_ids[slot]);
        retained_bytes += old_header_size() + sized_words[slot ? 7 : 3] * sizeof(Word);
      }
    }
    observed = total; major_collect();
#ifndef USE_BOEHM
    assert(stats.old_live_bytes == retained_bytes);
#else
    (void)retained_bytes;
    GC_reachable_here(anchor); GC_reachable_here(atomic_roots[0]); GC_reachable_here(atomic_roots[1]);
#endif
    atomic_roots[0] = atomic_roots[1] = head = anchor = 0;
    root_pop(&r1); root_pop(&r0); root_pop(&a); root_pop(&h);
    return total;
  } else {
    int ephemeral = strcmp(profile, "ephemeral") == 0;
    int mutation = strcmp(profile, "mutation") == 0;
    assert(ephemeral || mutation || strcmp(profile, "list") == 0);
    if (mutation) {
      anchor = work_allocate(list_layout()); minor_collect();
    }
    for (size_t i = 0; i < count; ++i) {
      Word node = work_allocate(list_layout());
      work_store(list_layout(), node, 0, integer(i)); work_store(list_layout(), node, 1, head); head = node;
      if ((ephemeral && (i + 1) % 256 == 0) || (mutation && (i + 1) % 64 == 0)) {
        if (mutation) work_store(list_layout(), anchor, 1, head);
        total += sum_list(head); head = 0;
      }
    }
    total += sum_list(head);
  }
  observed = total;
  /* Final collection makes old_live_bytes precise for the roots still retained here. */
  major_collect();
#ifndef USE_BOEHM
  if (strcmp(profile, "mixed") == 0)
    assert(stats.old_live_bytes == ((count + 63) / 64) * (old_header_size() + 3 * sizeof(Word)));
#endif
#ifdef USE_BOEHM
  GC_reachable_here(head); GC_reachable_here(anchor);
#endif
  head = anchor = 0; root_pop(&a); root_pop(&h);
  return total;
}
static double now(void) {
  struct timespec time; int status = clock_gettime(CLOCK_MONOTONIC, &time); assert(status == 0);
  return (double)time.tv_sec + (double)time.tv_nsec / 1e9;
}
int main(int argc, char **argv) {
  if (argc >= 2 && strcmp(argv[1], "--selftest") == 0) {
    heap_init(240); selftest(argc == 3 ? argv[2] : NULL); heap_destroy(); return 0;
  }
  if (argc != 4) { fprintf(stderr, "usage: %s PROFILE COUNT NURSERY_BYTES\n", argv[0]); return 2; }
  size_t count = strtoull(argv[2], NULL, 10), capacity = strtoull(argv[3], NULL, 10);
  assert(count > 0 && count < UINT64_C(1000000000) && capacity >= 240 && capacity <= SIZE_MAX / 4);
  heap_init(capacity);
  double preparation_start = now();
  prepare_workload();
  double preparation_seconds = now() - preparation_start;
  size_t descriptor_bytes_after_prepare = stats.descriptor_bytes;
  double start = now(); uint64_t checksum = workload(argv[1], count); double elapsed = now() - start;
  assert(checksum == (uint64_t)count * (count - 1) / 2);
  printf("{\"profile\":\"%s\",\"count\":%zu,\"checksum\":%" PRIu64 ",\"elapsed_seconds\":%.9f,",
         argv[1], count, checksum, elapsed);
  print_stats();
  printf(",\"layout_manifest_bytes\":%zu,\"preparation_seconds\":%.9f,\"descriptor_bytes_after_prepare\":%zu",
         sizeof layouts, preparation_seconds, descriptor_bytes_after_prepare);
  struct rusage usage; int status = getrusage(RUSAGE_SELF, &usage); assert(status == 0);
#ifdef __APPLE__
  size_t peak_rss = (size_t)usage.ru_maxrss;
#else
  size_t peak_rss = (size_t)usage.ru_maxrss * 1024;
#endif
  printf(",\"process_peak_rss_bytes\":%zu}\n", peak_rss);
  heap_destroy(); return 0;
}
